statement-execution-processor.statement:
begin
execute immediate 'create and compile java source named "{0}" as {1}';
end;

declare
    v_owner_name VARCHAR2(128) := {0};
    v_count INTEGER;
begin
    select count(1)
            into v_count
            from [PREFIX]_TABLES
           where OWNER = REGEXP_REPLACE(v_owner_name, '^"|"$', '')
             and TABLE_NAME = 'CREATE$JAVA$LOB$TABLE';

    if v_count = 0 THEN
        execute immediate 'create table '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" (
                    "NAME" VARCHAR2(700) PRIMARY KEY,
                    "LOB" BLOB,
                    "LOADTIME" DATE)';
    end if;
end;

declare
    v_owner_name VARCHAR2(128) := {0};
    v_count INTEGER;
begin
    select count(1)
            into v_count
            from USER_TABLES
           where USER = REGEXP_REPLACE(v_owner_name, '^"|"$', '')
             and TABLE_NAME = 'CREATE$JAVA$LOB$TABLE';

    if v_count = 0 THEN
        execute immediate 'create table '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" (
                    "NAME" VARCHAR2(700) PRIMARY KEY,
                    "LOB" BLOB,
                    "LOADTIME" DATE)';
    end if;
end;

declare
    v_owner_name VARCHAR2(128) := {0};
    v_resource_name VARCHAR2(700) := {1};
    v_content BLOB := {2};
    v_content_id VARCHAR2(128) := SYS_GUID();
begin
    execute immediate 'insert into '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" ("NAME", "LOB", "LOADTIME") VALUES ('''||v_content_id||''', :1, SYSDATE)' using v_content;

    IF v_content IS NULL THEN
        execute immediate 'create or replace java resource named '||v_owner_name||'.'||v_resource_name||' using blob (select EMPTY_BLOB() from DUAL)';
    ELSE
        execute immediate 'create or replace java resource named '||v_owner_name||'.'||v_resource_name||' using blob "LOB" from '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" where "NAME" = '''||v_content_id||'''';
    END IF;
    execute immediate 'delete '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" where "NAME" = '''||v_content_id||'''';
exception
    when others then
        execute immediate 'delete '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" where "NAME" = '''||v_content_id||'''';
    raise;
end;

declare
    v_owner_name VARCHAR2(128) := {0};
    v_class_name VARCHAR2(700) := {1};
    v_content BLOB := {2};
    v_content_id VARCHAR2(128) := SYS_GUID();
begin
    execute immediate 'insert into '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" ("NAME", "LOB", "LOADTIME") VALUES ('''||v_content_id||''', :1, SYSDATE)' using v_content;
    execute immediate 'create java class schema '||v_owner_name||' using blob select "LOB" from '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" where "NAME" = '''||v_content_id||'''';
    execute immediate 'delete '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" where "NAME" = '''||v_content_id||'''';
exception
    when others then
        execute immediate 'delete '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" where "NAME" = '''||v_content_id||'''';
    raise;
end;

declare
    v_owner_name VARCHAR2(128) := {0};
