    execute immediate 'create java source named '||v_owner_name||'.'||v_class_name||' using blob select "LOB" from '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" where "NAME" = '''||v_content_id||'''';
    execute immediate 'delete '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" where "NAME" = '''||v_content_id||'''';
exception
    when others then
        execute immediate 'delete '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" where "NAME" = '''||v_content_id||'''';
