end;

declare
    v_owner_name VARCHAR2(128) := {0};
    v_class_name VARCHAR2(700) := {1};
    v_content BLOB := {2};
    v_content_id VARCHAR2(128) := SYS_GUID();
begin
    execute immediate 'insert into '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" ("NAME", "LOB", "LOADTIME") VALUES ('''||v_content_id||''', :1, SYSDATE)' using v_content;
    execute immediate 'create or replace java source named '||v_owner_name||'.'||v_class_name||' using blob select "LOB" from '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" where "NAME" = '''||v_content_id||'''';
    execute immediate 'delete '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" where "NAME" = '''||v_content_id||'''';
exception
    when others then
        execute immediate 'delete '||v_owner_name||'."CREATE$JAVA$LOB$TABLE" where "NAME" = '''||v_content_id||'''';
    raise;
end;

declare
    v_owner_name VARCHAR2(128) := {0};
    v_class_name VARCHAR2(700) := {1};
begin
    begin
        execute immediate 'drop java source '||v_owner_name||'.'||v_class_name;
    exception
        when others then
            if SQLCODE != -4043 then raise; end if;
    end;

    begin
        execute immediate 'drop java class '||v_owner_name||'.'||v_class_name;
    exception
        when others then
            if SQLCODE != -4043 then raise; end if;
    end;
end;

declare
    result varchar2(4000);
begin
    result := dbms_java.set_property('sun.tools.javac.Main.args', 'g');
    dbms_java.set_compiler_option('{0}', 'debug', '{1}');
end;

begin
    execute immediate 'alter JAVA SOURCE {0}.{1} compile';
exception
when others then
    execute immediate 'alter JAVA CLASS {0}.{1} compile';
end;
